def lookup_astrology_kb(query: str) -> list[str]:
    """
    Parses natural language queries to search for matching planet-in-sign or
    planet-in-house interpretations from the local catalog.
    """
    normalized = query.lower().strip()
    matches = []
    
    # 1. Search for Planet-in-Sign matches
    # Keys in PLANET_IN_SIGN are: Sun, Moon, Mercury, Venus, Mars, Jupiter, Saturn
    for planet, signs in PLANET_IN_SIGN.items():
        if planet.lower() in normalized:
            for sign, text in signs.items():
                if sign.lower() in normalized:
                    matches.append(text)
                    
    # 2. Search for Planet-in-House matches
    # Keys in PLANET_IN_HOUSE are: Sun, Moon, Mars, Venus, Jupiter, Saturn
    for planet, houses in PLANET_IN_HOUSE.items():
        if planet.lower() in normalized:
            for house_key, house_num in HOUSE_MAP.items():
                if house_key in normalized:
                    if house_num in houses:
                        matches.append(houses[house_num])
                        break
                        
    # Limit to 3 matches max
    if matches:
        return matches[:3]
        
    # Default fallback
    return ["I don't have specific information about that placement, but I can offer general guidance based on your chart."]
